esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // take a parameter which the test will range over
    function run(uint amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // this contract deployed C in the harness, so it is the owner
        // ensure we have enough balance in this test contract to attempt transfers if needed
        if (address(this).balance < amt) {
            // nothing we can do; make the property vacuously hold by requiring a simple condition
            require(true);
        }

        // read before-values
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // attempt withdraw call (top-level state-changing call). We choose withdraw(amt);
        bool reverted;
        c.withdraw(amt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // If the call reverted, neither balance nor depositsCount changed.
        // If it did not revert, balance decreased by exactly amt (or to zero if amt > beforeBal due to transfer semantics), and depositsCount unchanged.
        // However, transfer will send up to _value; since withdraw forwards the exact uint via transfer, a successful call implies beforeBal >= amt and afterBal == beforeBal - amt.
        assert(
            reverted
            ? (afterCount == beforeCount && afterBal == beforeBal)
            : (afterCount == beforeCount && beforeBal >= amt && afterBal == beforeBal - amt)
        );
    }

    // accept Ether if C sends back to this test contract
    receive() external payable { }
}

